#define sqrt3 1.732050808

bool reverse = false;
float rnd = 0.;

float hash12(vec2 p)
{
    p = fract(p * vec2(5.3983, 5.4427));
    p += dot(p.yx, p.xy + vec2(21.5351, 14.3137));
    return fract(p.x * p.y * 95.4337);
}

float smin(float a, float b, float k)
{
	float h = clamp(0.5 + 0.5 *(b - a) / k, 0.0, 1.0);
	return mix(b, a, h) - k *h *(1.0 - h);
}

// distance to equilateral triangle
// Equilateral triangle is defined by
// max(-2y, y-x*sqrt3, y+x*sqrt3) = R
// R is the circumradius
float tri(vec2 p, float r)
{
    return abs(max(-2.*p.y, max(p.y-sqrt3*p.x, p.y+sqrt3*p.x))-r);
}

float noise(vec2 p)
{
    if(reverse) p.y = -p.y;
    return abs(tri(p+.55*tri(p.yx*2., 0.5+.5*rnd), 0.1));
}

vec3 drawTri(vec2 p, float r)
{    
    return 1.-smoothstep(0.0, 0.015, abs(tri(p, r))-0.03 + 0.02 * noise(p)) * vec3(1.); 
}

vec2 symm(float a, float b, float c, vec2 p)
{
    float x = ((b*b-a*a)*p.x-2.0*a*b*p.y-2.0*a*c) / (a*a+b*b);
    float y = ((a*a-b*b)*p.y-2.0*a*b*p.x-2.0*b*c) / (a*a+b*b);
    return vec2(x,y);
}

// distance of p to the line segment of p1, p2
float distToEdge(vec2 p1, vec2 p2, vec2 p)
{
    vec2 d = p2 - p1;
    vec2 v = vec2(1,-1);
    return abs(dot(d.yx*v, p) + dot(d*v, p1.yx)) / length(d);
}

vec2 p0, p1, p2;

float distToEdges(vec2 p)
{
    float d = distToEdge(p0, p2, p);
    float d2 = distToEdge(p0, p1, p);
    float d3 = distToEdge(p1, p2, p);
    return smin(d,smin(d2,d3,.05),.05);
}


// use the distance to the edges as height, for calculating normal
float height(vec2 p)
{
    float d = min(0.13, distToEdges(p));
    return min(d, 0.03 * noise(p) + 0.1);
}

vec3 getNormal(vec2 p)
{
    vec2 eps=vec2(0.03,0.0);
    vec3 n=vec3(height(p-eps.xy)-height(p+eps.xy),
                height(p-eps.yx)-height(p+eps.yx),
                2.0*eps.x);

    return normalize(n);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec2 p = uv * 2. - 1.;
    p.x *= iResolution.x / iResolution.y;
    //p*=1.2;
    p.x += iTime * 0.1;

    // simplex tiling
    vec2 i = floor(p + vec2(0.5*p.y, 0.)); 
    vec2 a = p - i + vec2(0.5*i.y, 0.); 

    // check which triangle the current pixel is in
    float m = step(a.y, 2. * a.x); 
    vec2 o = vec2(m, 1. - m);

    // the coord of the three vertices
    p0 = vec2(0);
    p1 = o - vec2(.5 * (1. - m), 0.);
    p2 = vec2(.5, 1.);

    vec2 center = (p0 + p1 + p2) / 3.;

    p0 -= center;
    p1 -= center;
    p2 -= center;
    a -= center;

    // min distance to the 3 edges of the triangle
    float d = distToEdges(a);

    vec3 col = vec3(1);

    reverse = m > 0.;
    rnd = hash12(i);

    d = smoothstep(0., 0.1, d);
    vec3 n = getNormal(a), ld = normalize(vec3(1.,1.,2.)); 

    // shading
    col *= 1.1*max(0., dot(n, ld)) * vec3(1., .8, 0.5) + 
            pow(max(0.0,dot(reflect(normalize(vec3(3,0,-1.)),n),ld)),32.);
    col *= .5 + .5 * cos(6.28318 * (vec3(6) * d + vec3(0.23,0.2,0.15)));

    // darken the edge between triangles
    col *= smoothstep(.0,0.1,d);


    // drawing the sierpinski
    if(reverse) a.y = -a.y;

    p = a*vec2(2.5, 2.2) * 1.35;
    float s=1.0;

    float iter = mod(floor(iTime),9.0);
    for(int i = 0; i < 4; ++i)
    {
        if(i < int(iter+0.5))
        {
            s*=0.5;
            col += drawTri(p,s) * .1;

            if(p.y+sqrt3*p.x>s)// Bottom right triangle
                p=symm(sqrt3/3., 1.0, 0., p);// Folding along y+1/3*x

            if(p.y-sqrt3*p.x>s)// Bottom left triangle
                p=symm(-sqrt3/3., 1.0, 0., p);// Folding along y-1/3*x

            p.y+=s;
        }
        else
        {
            // The animation
            float a=-2.0*fract(iTime);
            col+=drawTri(vec2(p.x*cos(a)-p.y*sin(a), p.y*cos(a)+p.x*sin(a)),
                     fract(iTime)*s*0.5) * .05;
        }
    }
    col*=pow(16.0*uv.x*uv.y*(1.0-uv.x)*(1.0-uv.y), 0.1);
    fragColor.xyz = col;
}
